# å®Œæ•´ç§»æ¤fetch_nickname.pyçš„æ ¸å¿ƒåŠŸèƒ½
class NicknameFetcher:
    """æŠ“å–æ˜µç§°ï¼›å¿…è¦æ—¶åœ¨å‰å° Chromium ä¸­ç­‰å¾…ç”¨æˆ·å®Œæˆå¹³å°éªŒè¯ã€‚"""

    verification_markers = (
        'éªŒè¯ç ä¸­é—´é¡µ', 'å®‰å…¨éªŒè¯', 'äººæœºéªŒè¯', 'æ»‘åŠ¨éªŒè¯',
        'æ‹–åŠ¨æ»‘å—', 'å®ŒæˆéªŒè¯', 'éªŒè¯é€šè¿‡å',
    )

    def __init__(self, status_callback=None, stop_event=None):
        self.status_callback = status_callback
        self.stop_event = stop_event

    def notify(self, message):
        """å°†æµè§ˆå™¨çŠ¶æ€å®‰å…¨åœ°æ˜¾ç¤ºåˆ° GUI æ—¥å¿—ä¸­ã€‚"""
        if self.status_callback:
            self.status_callback(message)

    def is_verification_text(self, text):
        """åˆ¤æ–­é¡µé¢æ ‡é¢˜/æ­£æ–‡æ˜¯å¦ä¸ºå¹³å°éªŒè¯é¡µï¼Œè€Œä¸æ˜¯ç”¨æˆ·æ˜µç§°ã€‚"""
        return bool(text) and any(marker in text for marker in self.verification_markers)

    async def wait_for_manual_verification(self, page, timeout=300):
        """æ£€æµ‹åˆ°éªŒè¯é¡µæ—¶ä¿æŒå‰å°æµè§ˆå™¨æ‰“å¼€ï¼Œç­‰å¾…ç”¨æˆ·æ‰‹å·¥å®ŒæˆéªŒè¯ã€‚"""
        async def page_requires_verification():
            try:
                title = await page.title()
                if self.is_verification_text(title):
                    return True
                body = await page.locator('body').inner_text(timeout=2_000)
                return self.is_verification_text(body)
            except Exception:
                return False

        if not await page_requires_verification():
            return True

        self.notify('æ£€æµ‹åˆ°å¹³å°éªŒè¯ï¼šå·²æ‰“å¼€å‰å°æµè§ˆå™¨ï¼Œè¯·æ‰‹å·¥å®ŒæˆéªŒè¯ï¼›å®Œæˆåç¨‹åºä¼šè‡ªåŠ¨ç»§ç»­ã€‚')
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if self.stop_event and self.stop_event.is_set():
                self.notify('å·²åœæ­¢ç­‰å¾…äººå·¥éªŒè¯ã€‚')
                return False
            if not await page_requires_verification():
                self.notify('éªŒè¯å·²å®Œæˆï¼Œç»§ç»­æŠ“å–æ˜µç§°ã€‚')
                await asyncio.sleep(2)
                return True
            await asyncio.sleep(1)

        self.notify('ç­‰å¾…äººå·¥éªŒè¯è¶…æ—¶ï¼ˆ5 åˆ†é’Ÿï¼‰ï¼Œå·²è·³è¿‡è¯¥åœ°å€ã€‚')
        return False

    def is_douyin(self, url):
        return 'douyin.com' in url.lower()

    def is_xiaohongshu(self, url):
        return any(x in url.lower() for x in ['xiaohongshu.com', 'xhslink.com', 'xhs.cn'])

    def clean_douyin_title(self, title):
        if not title:
            return None
        t = title.strip()
        if self.is_verification_text(t):
            return None
        if ' - ' in t:
            t = t.split(' - ')[0].strip()
        for suffix in ['çš„æŠ–éŸ³ä½œå“', 'çš„æŠ–éŸ³', 'çš„ä¸»é¡µ']:
            if t.endswith(suffix):
                t = t[:-len(suffix)]
                break
        if t == '-':
            return ''
        return t.strip()

    def clean_douyin_desc(self, desc):
        if not desc:
            return None
        t = desc.strip()
        if self.is_verification_text(t):
            return None
        if ' - ' not in t:
            return None
        last = t.rsplit(' - ', 1)[1].strip()
        last = re.sub(r'äº\d+å‘å¸ƒåœ¨æŠ–éŸ³.*', '', last)
        return last if last and not self.is_verification_text(last) else None

    def clean_xiaohongshu_title(self, title):
        if not title:
            return None
        t = title.strip()
        if self.is_verification_text(t):
            return None
        for sep in [' - ', ' | ']:
            if sep in t:
                parts = t.split(sep)
                if len(parts) >= 2:
                    candidate = parts[-1].strip()
                    candidate = re.sub(r'\d+èµ$', '', candidate)
                    if candidate:
                        return candidate if not self.is_verification_text(candidate) else None
                break
        return t.strip()

    def fetch_html_requests(self, url, timeout=10):
        headers = {
            'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1',
            'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
        }
        try:
            resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
            resp.encoding = 'utf-8'
            return resp.text, resp.url
        except Exception:
            return None, None

    def extract_douyin_from_html(self, html):
        if not html:
            return None

        m = re.search(r'<meta[^>]+(?:name|property)=["\'](?:og:)?description["\'][^>]+content=["\']([^"\']+)["\']', html, re.I)
        if m:
            desc = m.group(1)
            nick = self.clean_douyin_desc(desc)
            if nick: return nick

        m = re.search(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+(?:name|property)=["\'](?:og:)?description["\']', html, re.I)
        if m:
            desc = m.group(1)
            nick = self.clean_douyin_desc(desc)
            if nick: return nick

        m = re.search(r'<meta[^>]+property=["\']og:title["\'][^>]+content=["\']([^"\']+)["\']', html, re.I)
        if m:
            return self.clean_douyin_title(m.group(1))
        m = re.search(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:title["\']', html, re.I)
        if m:
            return self.clean_douyin_title(m.group(1))

        m = re.search(r'dd-title=["\']([^"\']+)["\']', html)
        if m:
            return self.clean_douyin_title(m.group(1))

        m = re.search(r'<title[^>]*>([^<]+)</title>', html, re.I)
        if m:
            return self.clean_douyin_title(m.group(1))
        return None

    def extract_xiaohongshu_from_html(self, html):
        if not html:
            return None

        m = re.search(r'<meta[^>]+property=["\']og:title["\'][^>]+content=["\']([^"\']+)["\']', html, re.I)
        if m:
            return self.clean_xiaohongshu_title(m.group(1))
        m = re.search(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:title["\']', html, re.I)
        if m:
            return self.clean_xiaohongshu_title(m.group(1))

        m = re.search(r'<title[^>]*>([^<]+)</title>', html, re.I)
        if m:
            t = self.clean_xiaohongshu_title(m.group(1))
            if t and t not in ['å°çº¢ä¹¦', 'å°çº¢ä¹¦ - ä½ çš„ç”Ÿæ´»å…´è¶£ç¤¾åŒº']:
                return t
        return None

    async def fetch_douyin_with_playwright(self, url, timeout=25):
        from playwright.async_api import async_playwright

        async with async_playwright() as p:
            # è‡ªåŠ¨æ¢æµ‹æ‰“åŒ…ç¯å¢ƒä¸‹çš„ chromium è·¯å¾„
            executable_path = None
            if getattr(sys, 'frozen', False):
                base_path = getattr(sys, '_MEIPASS', os.path.dirname(sys.executable))
                # æ ¹æ®ä¹‹å‰ build_exe.py æ‰“åŒ…æ—¶çš„ç›®å½•åå¯»æ‰¾
                possible_exe = os.path.join(base_path, 'chrome-win', 'chrome.exe')
                if not os.path.exists(possible_exe):
                    possible_exe = os.path.join(base_path, 'chrome-win64', 'chrome.exe')
                if not os.path.exists(possible_exe):
                    possible_exe = os.path.join(base_path, 'chrome-win', 'chromium.exe') # linux/mac å¯èƒ½å«åˆ«çš„ï¼Œä½†æˆ‘ä»¬æ˜¯windowsæ‰“åŒ…
                if not os.path.exists(possible_exe):
                    possible_exe = os.path.join(base_path, 'chrome-win64', 'chromium.exe')
                if os.path.exists(possible_exe):
                    executable_path = possible_exe
                    
            if executable_path:
                browser = await p.chromium.launch(headless=False, executable_path=executable_path)
            else:
                try:
                    browser = await p.chromium.launch(headless=False)
                except Exception as e:
                    self.notify(f"æµè§ˆå™¨å¯åŠ¨å¤±è´¥: æ‰¾ä¸åˆ° Chromiumï¼Œè¯·å°è¯•è¿è¡Œ playwright install chromium ({str(e)})")
                    return None
                    
            context = await browser.new_context(
                user_agent='Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1',
                viewport={'width': 375, 'height': 812}
            )
            page = await context.new_page()
            await page.goto(url, timeout=timeout * 1000, wait_until='domcontentloaded')
            await asyncio.sleep(4)
            if not await self.wait_for_manual_verification(page):
                await browser.close()
                return None

            selectors = [
                'meta[property="og:description"]',
                'meta[name="description"]'
            ]
            for sel in selectors:
                try:
                    elem = await page.query_selector(sel)
                    if elem:
                        desc = await elem.get_attribute('content') or ''
                        nickname = self.clean_douyin_desc(desc)
                        if nickname:
                            await browser.close()
                            return nickname
                except Exception:
                    pass

            title = await page.title()
            await browser.close()
            return self.clean_douyin_title(title)

    async def fetch_xiaohongshu_with_playwright(self, url, timeout=25):
        from playwright.async_api import async_playwright

        async with async_playwright() as p:
            # è‡ªåŠ¨æ¢æµ‹æ‰“åŒ…ç¯å¢ƒä¸‹çš„ chromium è·¯å¾„
            executable_path = None
            if getattr(sys, 'frozen', False):
                base_path = getattr(sys, '_MEIPASS', os.path.dirname(sys.executable))
                possible_exe = os.path.join(base_path, 'chrome-win', 'chrome.exe')
                if not os.path.exists(possible_exe):
                    possible_exe = os.path.join(base_path, 'chrome-win64', 'chrome.exe')
                if not os.path.exists(possible_exe):
                    possible_exe = os.path.join(base_path, 'chrome-win', 'chromium.exe')
